<?php get_header(); ?>
<main class="sluyu-container sluyu-main"><div class="sluyu-content-layout"><article class="sluyu-article"><?php while (have_posts()) : the_post(); $version = wuai_sluyu_post_meta(get_the_ID(), 'version'); $platform = wuai_sluyu_post_meta(get_the_ID(), 'platform'); $download = wuai_sluyu_post_meta(get_the_ID(), 'download_url'); $password = wuai_sluyu_post_meta(get_the_ID(), 'download_password'); ?><header class="sluyu-article-header"><div class="sluyu-article-cat"><?php the_category(' · '); ?></div><h1><?php the_title(); ?></h1><div class="sluyu-article-meta"><span><?php echo esc_html(get_the_date('Y年m月d日')); ?></span><span><?php echo esc_html(get_the_author()); ?></span><span><?php echo esc_html(number_format_i18n(get_comments_number())); ?> 条评论</span></div></header><?php if (has_post_thumbnail()) : ?><figure class="sluyu-featured"><img src="<?php echo esc_url(get_the_post_thumbnail_url(get_the_ID(), 'large')); ?>" alt="<?php the_title_attribute(); ?>"></figure><?php endif; ?><div class="sluyu-entry"><?php the_content(); ?></div><?php if ($version || $platform) : ?><div class="sluyu-facts"><div><small>版本</small><strong><?php echo esc_html($version ?: '最新版'); ?></strong></div><div><small>平台</small><strong><?php echo esc_html($platform ?: 'Windows'); ?></strong></div></div><?php endif; ?><?php if (function_exists('zibpay_posts_pay_content')) : ?><div class="sluyu-zibpay"><?php zibpay_posts_pay_content(); ?></div><?php endif; ?><?php if ($download) : ?><section class="sluyu-download"><h2>网盘下载</h2><p>资源链接已整理，请按需下载。</p><div><a href="<?php echo esc_url($download); ?>" target="_blank" rel="nofollow noopener">打开下载链接</a><?php if ($password) : ?><code>提取码：<?php echo esc_html($password); ?></code><?php endif; ?></div></section><?php endif; ?><?php comments_template(); endwhile; ?></article><?php get_sidebar(); ?></div></main>
<?php get_footer(); ?>
